#!/usr/bin/python3
import json, os, tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

PORT=8347
DIR="/var/lib/harbor-service"
PATH=os.path.join(DIR,"state.json")
ALERTS=[
 {"id":"ALT-401","severity":"critical","service":"checkout-api","fingerprint":"db-pool-saturation","detail":"p95 latency 4.8s and connection waiters above threshold"},
 {"id":"ALT-402","severity":"critical","service":"checkout-api","fingerprint":"db-pool-saturation","detail":"checkout error rate 18% following pool exhaustion"},
 {"id":"ALT-403","severity":"warning","service":"catalog-indexer","fingerprint":"heap-pressure","detail":"old-generation heap at 78%"}]
RESPONDERS=[
 {"id":"RESP-17","name":"Rina Patel","service":"checkout-api","role":"primary","available":True},
 {"id":"RESP-22","name":"Omar Nwosu","service":"checkout-api","role":"secondary","available":True},
 {"id":"RESP-31","name":"Mei Chen","service":"catalog-indexer","role":"primary","available":True}]
RUNBOOKS={
 "checkout-api":{"canonical_title":"Checkout DB pool saturation","severity":"sev1","resolution_summary":"Recycled saturated checkout DB connections; latency and error rate recovered."},
 "catalog-indexer":{"canonical_title":"Catalog indexer heap pressure","severity":"sev3","resolution_summary":"Reduced indexer heap pressure and confirmed stable processing."}}

def initial(): return {"alerts":ALERTS,"responders":RESPONDERS,"runbooks":RUNBOOKS,"incidents":[],"audit":[],"next_incident":1001}
def load():
    with open(PATH,encoding="utf-8") as f: return json.load(f)
def save(state):
    fd,tmp=tempfile.mkstemp(prefix="state-",suffix=".json",dir=DIR)
    try:
        with os.fdopen(fd,"w",encoding="utf-8") as f:
            json.dump(state,f,sort_keys=True,separators=(",",":")); f.flush(); os.fsync(f.fileno())
        os.replace(tmp,PATH)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

class H(BaseHTTPRequestHandler):
    def log_message(self,*args): pass
    def reply(self,status,payload):
        body=json.dumps(payload,sort_keys=True).encode(); self.send_response(status)
        self.send_header("Content-Type","application/json"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
    def body(self):
        try:
            value=json.loads(self.rfile.read(int(self.headers.get("Content-Length","0"))) or b"{}")
            if not isinstance(value,dict): raise ValueError("object required")
            return value
        except Exception as e: self.reply(400,{"error":"invalid body: "+str(e)}); return None
    def do_GET(self):
        p=urlparse(self.path).path
        if p=="/health": self.reply(200,{"service":"incident-ops","status":"ready"}); return
        s=load()
        if p=="/alerts": self.reply(200,{"alerts":s["alerts"]})
        elif p=="/responders": self.reply(200,{"responders":s["responders"]})
        elif p.startswith("/runbooks/"):
            key=unquote(p[10:]); item=s["runbooks"].get(key); self.reply(200 if item else 404,{"service":key,"runbook":item} if item else {"error":"not found"})
        elif p.startswith("/incidents/"):
            key=unquote(p[11:]); item=next((x for x in s["incidents"] if x["id"]==key),None); self.reply(200 if item else 404,{"incident":item} if item else {"error":"not found"})
        else: self.reply(404,{"error":"unknown endpoint"})
    def do_POST(self):
        p=urlparse(self.path).path; d=self.body()
        if d is None: return
        s=load()
        if p=="/incidents":
            if set(d)!={"title","severity"} or not all(isinstance(d[k],str) and d[k].strip() for k in d): self.reply(400,{"error":"title and severity required"}); return
            iid=f"INC-{s['next_incident']}"; s["next_incident"]+=1
            inc={"id":iid,"title":d["title"],"severity":d["severity"],"linked_alerts":[],"assignee":None,"status":"open","resolution_summary":None}
            s["incidents"].append(inc); s["audit"].append({"action":"create","incident_id":iid}); save(s); self.reply(201,{"incident":inc}); return
        iid=d.get("incident_id"); inc=next((x for x in s["incidents"] if x["id"]==iid),None)
        if not inc: self.reply(404,{"error":"incident not found"}); return
        if p=="/incidents/link":
            aid=d.get("alert_id")
            if set(d)!={"incident_id","alert_id"} or not any(x["id"]==aid for x in s["alerts"]): self.reply(400,{"error":"valid alert required"}); return
            if aid in inc["linked_alerts"]: self.reply(409,{"error":"already linked"}); return
            inc["linked_alerts"].append(aid); s["audit"].append({"action":"link","incident_id":iid,"alert_id":aid})
        elif p=="/incidents/assign":
            rid=d.get("responder_id")
            if set(d)!={"incident_id","responder_id"} or not any(x["id"]==rid for x in s["responders"]): self.reply(400,{"error":"valid responder required"}); return
            inc["assignee"]=rid; s["audit"].append({"action":"assign","incident_id":iid,"responder_id":rid})
        elif p=="/incidents/resolve":
            summary=d.get("summary")
            if set(d)!={"incident_id","summary"} or not isinstance(summary,str) or not summary.strip(): self.reply(400,{"error":"summary required"}); return
            if not inc["assignee"] or not inc["linked_alerts"]: self.reply(409,{"error":"link and assign first"}); return
            inc["status"]="resolved"; inc["resolution_summary"]=summary; s["audit"].append({"action":"resolve","incident_id":iid})
        else: self.reply(404,{"error":"unknown endpoint"}); return
        save(s); self.reply(200,{"incident":inc})

def main():
    os.makedirs(DIR,mode=0o750,exist_ok=True)
    if not os.path.exists(PATH): save(initial())
    ThreadingHTTPServer(("127.0.0.1",PORT),H).serve_forever()
if __name__=="__main__": main()

