{"name":"get_runbook","method":"GET","path":"/runbooks/{service}","mutating":false,"description":"Get a service's canonical incident title, severity, and required resolution summary.","params":[{"name":"service","type":"string","required":true,"description":"Exact service name from an alert"}]},
{"name":"list_responders","method":"GET","path":"/responders","mutating":false,"description":"List responders with service ownership, rotation role, and availability."},
{"name":"create_incident","method":"POST","path":"/incidents","mutating":true,"description":"Create an incident and return its incident_id.","params":[{"name":"title","type":"string","required":true,"description":"Incident title"},{"name":"severity","type":"string","required":true,"description":"Incident severity"}]},
{"name":"link_alert","method":"POST","path":"/incidents/link","mutating":true,"description":"Link an active alert to an incident.","params":[{"name":"incident_id","type":"string","required":true,"description":"Incident ID"},{"name":"alert_id","type":"string","required":true,"description":"Alert ID"}]},
{"name":"assign_incident","method":"POST","path":"/incidents/assign","mutating":true,"description":"Assign an incident to a responder.","params":[{"name":"incident_id","type":"string","required":true,"description":"Incident ID"},{"name":"responder_id","type":"string","required":true,"description":"Responder ID"}]},
{"name":"resolve_incident","method":"POST","path":"/incidents/resolve","mutating":true,"description":"Resolve an assigned incident with a summary.","params":[{"name":"incident_id","type":"string","required":true,"description":"Incident ID"},{"name":"summary","type":"string","required":true,"description":"Runbook-required resolution summary"}]},
{"name":"get_incident","method":"GET","path":"/incidents/{incident_id}","mutating":false,"description":"Inspect an incident's complete current state.","params":[{"name":"incident_id","type":"string","required":true,"description":"Incident ID"}]}
]}
